import type { ComponentInterface } from '@stencil/core';
import { VirtualizerController } from '@src/framework/stencil-virtual';
import { getColumnsToVirtualize } from '../helpers';

import {
  type Virtualizer,
  type VirtualizerOptions,
  type PartialKeys,
  measureElement,
  type VirtualItem,
} from '@tanstack/virtual-core';
import type { Row, RowData, HeaderGroup, Column } from '@byted-keystone/table';
import type { CSSProperties } from '@src/shared/dom';
import type { TableDynamicRenderMode, TableSize, TableScrollPosition, TableScrollToPositionOptions } from '../types';

const DEFAULT_ROW_HEIGHT: Record<TableSize, number> = {
  md: 52,
  sm: 40,
};

export interface VirtualTableVirtualizerOptions {
  row?: PartialKeys<
    VirtualizerOptions<HTMLDivElement, HTMLTableRowElement>,
    'observeElementRect' | 'observeElementOffset' | 'scrollToFn' | 'count' | 'getScrollElement' | 'estimateSize'
  >;
  column?: PartialKeys<
    VirtualizerOptions<HTMLDivElement, HTMLTableCellElement>,
    'observeElementRect' | 'observeElementOffset' | 'scrollToFn' | 'count' | 'getScrollElement' | 'estimateSize'
  >;
}

export interface VirtualTableDynamicSlotParams {
  rows: Row<RowData>[];
  headerGroups: HeaderGroup<RowData>[];
  virtualColumnIndexes: number[];
  includeBodyCells: boolean;
}

export interface VirtualTableRenderState {
  rowsToVirtualize: Row<RowData>[];
  topRows: Row<RowData>[];
  virtualRows: VirtualItem[];
  virtualColumns: VirtualItem[];
  virtualColumnIndexes: number[];
  visibleFlatColumns: Column<RowData, unknown>[];
  virtualRowStyle: CSSProperties;
}

type HostComponent = ComponentInterface & { el: HTMLElement } & { isConnected?: boolean };

export interface VirtualTableControllerHost {
  host: HostComponent;
  getRowVirtualizer: () => Virtualizer<HTMLDivElement, HTMLTableRowElement> | undefined;
  setRowVirtualizer: (virtualizer?: Virtualizer<HTMLDivElement, HTMLTableRowElement>) => void;
  getColumnVirtualizer: () => Virtualizer<HTMLDivElement, HTMLTableCellElement> | undefined;
  setColumnVirtualizer: (virtualizer?: Virtualizer<HTMLDivElement, HTMLTableCellElement>) => void;
  getWrapperEl: () => HTMLDivElement | null;
  getEstimatedRowHeight: (index: number) => number | undefined;
  getSize: () => TableSize | undefined;
  getVirtualizerOptions: () => VirtualTableVirtualizerOptions | undefined;
  getRowsToVirtualize: () => Row<RowData>[];
  getVisibleFlatColumns: () => Column<RowData, unknown>[];
  getHeaderGroups: () => HeaderGroup<RowData>[];
  getTopRows: () => Row<RowData>[];
  getDataSourceLength: () => number;
  getCurrentDragging: () => string | null;
  getDynamicSlots: (params: VirtualTableDynamicSlotParams) => unknown[];
  commitDynamicRenderDeps: (nodes: unknown[]) => void;
  scrollToWrapper: (options?: TableScrollToPositionOptions) => void;
  getDynamicRenderMode: () => TableDynamicRenderMode;
  getIsRtl: () => boolean;
}

const SCROLL_SETTLE_DELAY = 150;
const POST_SETTLE_RENDER_GRACE_PERIOD = 400;

export class VirtualTableController {
  private pendingRowSync = false;
  private lastStateFingerprint: string | null = null;
  private lastRenderedNodes: unknown[] = [];
  private rafId: number | null = null;
  private isScrolling = false;
  private scrollSettlingTimer: ReturnType<typeof setTimeout> | null = null;
  private postSettleGracePeriodUntil = 0;

  constructor(private readonly host: VirtualTableControllerHost) {}

  public initialize() {
    this.host.setRowVirtualizer(
      new VirtualizerController<HTMLDivElement, HTMLTableRowElement>(this.host.host, {
        count: this.host.getRowsToVirtualize().length,
        estimateSize: (index) =>
          this.host.getEstimatedRowHeight(index) || DEFAULT_ROW_HEIGHT[this.host.getSize() || 'md'],
        getScrollElement: () => this.host.getWrapperEl(),
        measureElement: (el, entry, instance) => measureElement(el, entry, instance),
        overscan: 4,
        ...this.host.getVirtualizerOptions()?.row,
      }).getVirtualizer(),
    );

    const columnsToVirtualize = getColumnsToVirtualize(this.host.getVisibleFlatColumns());
    this.host.setColumnVirtualizer(
      new VirtualizerController<HTMLDivElement, HTMLTableCellElement>(this.host.host, {
        count: columnsToVirtualize.length,
        estimateSize: (index) => columnsToVirtualize[index]?.getSize() ?? 0,
        getScrollElement: () => this.host.getWrapperEl(),
        horizontal: true,
        isRtl: this.host.getIsRtl(),
        overscan: 4,
        ...this.host.getVirtualizerOptions()?.column,
      }).getVirtualizer(),
    );
  }

  public markRowSyncPending() {
    this.pendingRowSync = true;
  }

  public flushPendingBeforeRender() {
    if (!this.pendingRowSync) {
      return;
    }

    this.pendingRowSync = false;
    this.syncRows();
  }

  public syncRows() {
    const rowVirtualizer = this.host.getRowVirtualizer();
    rowVirtualizer?.setOptions({
      ...rowVirtualizer.options,
      count: this.host.getRowsToVirtualize().length,
    });
    this.invalidateCaches();
  }

  public syncColumns() {
    const columnsToVirtualize = getColumnsToVirtualize(this.host.getVisibleFlatColumns());
    const columnVirtualizer = this.host.getColumnVirtualizer();

    columnVirtualizer?.setOptions({
      ...columnVirtualizer.options,
      estimateSize: (index) => columnsToVirtualize[index]?.getSize() ?? 0,
      count: columnsToVirtualize.length,
      isRtl: this.host.getIsRtl(),
    });
    this.invalidateCaches();
  }

  public notifyScroll(position: TableScrollPosition) {
    if (this.host.getDynamicRenderMode() !== 'settle-on-scroll') {
      return;
    }

    const isScrollable = !position.isAtTop || !position.isAtBottom || !position.isAtStart || !position.isAtEnd;
    const isInPostSettleGracePeriod = Date.now() < this.postSettleGracePeriodUntil;

    if (isInPostSettleGracePeriod) {
      return;
    }

    if (!this.isScrolling && isScrollable) {
      this.isScrolling = true;
      this.invalidateCaches();
      this.scheduleDynamicSlotUpdate();
    }

    if (this.scrollSettlingTimer) {
      clearTimeout(this.scrollSettlingTimer);
    }

    this.scrollSettlingTimer = setTimeout(() => {
      this.isScrolling = false;
      this.scrollSettlingTimer = null;
      this.postSettleGracePeriodUntil = Date.now() + POST_SETTLE_RENDER_GRACE_PERIOD;
      this.invalidateCaches();
      this.scheduleDynamicSlotUpdate();
    }, SCROLL_SETTLE_DELAY);
  }

  public scheduleDynamicSlotUpdate = () => {
    if (this.rafId) {
      return;
    }

    this.rafId = requestAnimationFrame(() => {
      this.performUpdateDynamicSlots();
      this.rafId = null;
    });
  };

  public invalidateCaches() {
    this.lastStateFingerprint = null;
  }

  public getRenderState(): VirtualTableRenderState {
    const rowsToVirtualize = this.host.getRowsToVirtualize();
    const topRows = this.host.getTopRows();
    const rowVirtualizer = this.host.getRowVirtualizer();
    const columnVirtualizer = this.host.getColumnVirtualizer();
    const virtualRows = rowVirtualizer?.getVirtualItems() ?? [];
    const virtualColumns = columnVirtualizer?.getVirtualItems() ?? [];
    const visibleFlatColumns = this.host.getVisibleFlatColumns();
    const virtualColumnIndexes = virtualColumns.map(({ index }) => index);

    return {
      rowsToVirtualize,
      topRows,
      virtualRows,
      virtualColumns,
      virtualColumnIndexes,
      visibleFlatColumns,
      virtualRowStyle:
        columnVirtualizer && virtualColumns.length > 0
          ? {
              '--ks-comp-table-virtual-padding-start': `${virtualColumns[0]?.start ?? 0}px`,
              '--ks-comp-table-virtual-padding-end': `${
                columnVirtualizer.getTotalSize() - (virtualColumns[virtualColumns.length - 1]?.end ?? 0)
              }px`,
            }
          : {},
    };
  }

  public scrollToPosition(options?: TableScrollToPositionOptions) {
    const { top, left, behavior } = options || {};
    const virtualScrollBehavior = behavior === 'smooth' ? 'smooth' : 'auto';
    const rowVirtualizer = this.host.getRowVirtualizer();
    const columnVirtualizer = this.host.getColumnVirtualizer();

    if (top !== undefined && left !== undefined) {
      this.host.scrollToWrapper({ top, left, behavior });
      return;
    }

    if (top !== undefined) {
      if (rowVirtualizer) {
        rowVirtualizer.scrollToOffset(top, { behavior: virtualScrollBehavior });
      } else {
        this.host.scrollToWrapper({ top, behavior });
      }
    }

    if (left !== undefined) {
      if (columnVirtualizer) {
        columnVirtualizer.scrollToOffset(left, { behavior: virtualScrollBehavior });
      } else {
        this.host.scrollToWrapper({ left, behavior });
      }
    }
  }

  private performUpdateDynamicSlots() {
    const virtualRowIndexes = this.host.getRowVirtualizer()?.getVirtualIndexes() ?? [];
    const virtualColumnIndexes = this.host.getColumnVirtualizer()?.getVirtualIndexes() ?? [];
    const currentFingerprint = [
      virtualRowIndexes.join(','),
      virtualColumnIndexes.join(','),
      this.host.getDataSourceLength(),
      this.host.getCurrentDragging(),
      this.host.getDynamicRenderMode(),
      this.isScrolling ? 'scrolling' : 'settled',
    ].join(':');

    if (currentFingerprint === this.lastStateFingerprint && this.lastRenderedNodes.length > 0) {
      return;
    }

    const visibleRows = virtualRowIndexes
      .map((index) => this.host.getRowsToVirtualize()[index])
      .filter((row): row is Row<RowData> => !!row && !row.getIsPinned())
      .concat(this.host.getTopRows());

    const newNodes = this.host.getDynamicSlots({
      rows: visibleRows,
      headerGroups: this.host.getHeaderGroups(),
      virtualColumnIndexes,
      includeBodyCells: !(this.host.getDynamicRenderMode() === 'settle-on-scroll' && this.isScrolling),
    });

    this.lastStateFingerprint = currentFingerprint;
    this.lastRenderedNodes = newNodes;
    this.host.commitDynamicRenderDeps(newNodes);
  }
}
