import type { Column, Header, Row, RowData } from '@byted-keystone/table';

export function getRowsToVirtualize(rows: Row<RowData>[]) {
  return rows.filter((row) => (!row.getIsPinned() && !row.getParentRow()) || row.getParentRow()?.getIsExpanded());
}

export function getColumnsToVirtualize(columns: Column<RowData>[]) {
  return columns.filter((column) => !column.getIsPinned());
}

export function getVirtualHeaders<TData>(headers: Header<TData, unknown>[], virtualIndexes: number[]) {
  if (!virtualIndexes.length || !headers.length) {
    return [];
  }

  const startVirtualIndex = virtualIndexes[0] ?? 0;
  const endVirtualIndex = virtualIndexes[virtualIndexes.length - 1] ?? 0;

  const result: Header<TData, unknown>[] = [];

  let currentLeafIndex = 0;

  for (const header of headers) {
    const headerStart = currentLeafIndex;
    const headerEnd = currentLeafIndex + header.colSpan - 1;

    currentLeafIndex += header.colSpan;

    // 判断是否与虚拟窗口有交集 (Intersection)
    // 只要 Header 的一部分在 [start, end] 范围内，就需要渲染它
    if (headerEnd >= startVirtualIndex && headerStart <= endVirtualIndex) {
      result.push(header);
    }

    // 如果 headerStart 已经超过了 endVirtualIndex，后面的都可以跳过了
    if (headerStart > endVirtualIndex) {
      break;
    }
  }

  return result;
}
