/* eslint-disable max-lines */
import { h, Host, Component, Prop, type ComponentInterface, Watch, VNode, State } from '@stencil/core';
import { throttle } from 'lodash-es';
import { DetailArgs } from '@src/shared/dom';
import { TableBodyRow, TableHeadRow, TableFootRow } from './components';
import { KsTable } from './ks-table';
import { DEFAULT_PAGE_SIZE, SELECTION_COLUMN_ID, getRowsToVirtualize, getVirtualHeaders } from './helpers';
import {
  VirtualTableController,
  type VirtualTableVirtualizerOptions,
  type VirtualTableRenderState,
} from './controllers/virtual-table.controller';

import type { Row, RowData, HeaderGroup, Header, Cell } from '@byted-keystone/table';
import { type Virtualizer, type VirtualItem } from '@tanstack/virtual-core';
import type {
  TableColumn,
  TableColumnGroup,
  TableFrameMode,
  TableDynamicRenderMode,
  TableRowPinningConfig,
  TableExpandableConfig,
  TableScrollToPositionOptions,
} from './types';
import { dir } from '@src/shared/i18n';

const prefix = 'table';

/**
 * @slot append - Content to display at the end of the table.
 * @slot empty - Content to display when the table has no data.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-virtual-table',
  styleUrl: 'ks-virtual-table.scss',
  shadow: true,
})
export class KsVirtualTable extends KsTable implements ComponentInterface {
  private rowVirtualizer?: Virtualizer<HTMLDivElement, HTMLTableRowElement>;
  private bodyCellDynamicSlotCache = new Map<string, unknown>();
  private readonly virtualController = new VirtualTableController({
    host: this,
    getRowVirtualizer: () => this.rowVirtualizer,
    setRowVirtualizer: (virtualizer) => {
      this.rowVirtualizer = virtualizer;
    },
    getColumnVirtualizer: () => this.columnVirtualizer,
    setColumnVirtualizer: (virtualizer) => {
      this.columnVirtualizer = virtualizer;
    },
    getWrapperEl: () => this.wrapperEl || null,
    getEstimatedRowHeight: (index) =>
      typeof this.estimatedRowHeight === 'function' ? this.estimatedRowHeight(index) : this.estimatedRowHeight,
    getSize: () => this.size,
    getVirtualizerOptions: () => this.virtualizerOptions,
    getRowsToVirtualize: () => getRowsToVirtualize(this.getTableRowModel()),
    getVisibleFlatColumns: () => this.table.getVisibleFlatColumns(),
    getHeaderGroups: () => this.table.getHeaderGroups(),
    getTopRows: () => this.table.getTopRows(),
    getDataSourceLength: () => this.dataSource.length,
    getCurrentDragging: () => this.currentDragging,
    getDynamicSlots: (params) => this.getDynamicSlots(params),
    commitDynamicRenderDeps: (nodes) => {
      this.setDynamicRenderDeps([...nodes, ...Object.values(this.headerDynamicRenderDeps).flat()]);
    },
    scrollToWrapper: (options) => this.scrollToWrapper(options),
    getDynamicRenderMode: () => this.dynamicRenderMode,
    getIsRtl: () => dir() === 'rtl',
  });
  // eslint-disable-next-line @stencil-community/own-props-must-be-private
  public override columnVirtualizer?: Virtualizer<HTMLDivElement, HTMLTableCellElement>;

  /** Key generator for slot key, default to use cell or header id. */
  @Prop() override slotKey = (instance: Header<RowData, unknown> | Cell<RowData, unknown>) => instance.id;

  /** Estimated height (px) of each row in the list, applied to the height of the row skeleton during loading. */
  @Prop() estimatedRowHeight?: number | ((index: number) => number);

  /** Whether the table frame fills the available height or follows content height. */
  @Prop() override frameMode: TableFrameMode = 'fill';

  /** virtualizer configuration */
  @Prop() virtualizerOptions?: VirtualTableVirtualizerOptions;

  /** Dynamic render mode for virtual rows. */
  @Prop() dynamicRenderMode: TableDynamicRenderMode = 'auto';

  // [None Manual Mode] update virtualizer when internal expanded state changed
  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('internalExpandedState')
  protected onInternalExpandedStateChange(): void {
    this.virtualController.markRowSyncPending();
  }
  // [Manual Mode] update virtualizer when expandable prop changed
  protected override expandableChanged(expandable: TableExpandableConfig) {
    super.expandableChanged(expandable);
    this.virtualController.syncRows();
  }

  protected override columnsChanged(columns: (TableColumn<RowData> | TableColumnGroup)[]): void {
    super.columnsChanged(columns);
    this.clearBodyCellDynamicSlotCache();
    this.virtualController.syncColumns();
  }

  protected override rowPinningChanged(cfg: TableRowPinningConfig, oldCfg: TableRowPinningConfig): void {
    super.rowPinningChanged(cfg, oldCfg);
    this.virtualController.syncRows();
  }

  protected override dataSourceChanged(dataSource: RowData[]): void {
    super.dataSourceChanged(dataSource);
    this.clearBodyCellDynamicSlotCache();
    this.virtualController.syncRows();
    this.virtualController.syncColumns();
  }

  protected override onResponsiveColumnWidthsChanged(): void {
    this.virtualController.syncColumns();
  }

  protected override getCssVariables = () => {
    const sortedColumns = this.getSortedVisibleFlatColumns();
    const { cssProperties, totalSize } = this.getColumnWidthCssVariables(sortedColumns);
    const availableWidth = this.wrapperEl?.clientWidth || this.el.clientWidth;
    if (totalSize < availableWidth) {
      const rest = availableWidth - totalSize;
      const last = sortedColumns.at(-1);
      if (last) {
        cssProperties[`--ks-comp-width-table-column-${last.id}`] = `${last.getSize() + rest}`;
      }
    }
    return cssProperties;
  };

  override componentWillLoad(): void {
    super.componentWillLoad();
    this.virtualController.initialize();
  }

  componentWillRender() {
    this.virtualController.flushPendingBeforeRender();
  }

  protected override updateDynamicSlots = this.virtualController.scheduleDynamicSlotUpdate;

  /* istanbul ignore next */
  protected override getDynamicSlots({
    rows,
    headerGroups,
    virtualColumnIndexes,
    includeBodyCells,
  }: {
    rows: Row<RowData>[];
    headerGroups: HeaderGroup<RowData>[];
    virtualColumnIndexes: number[];
    includeBodyCells: boolean;
  }) {
    const renderedNodes: unknown[] = [];

    headerGroups.forEach((headerGroup) => {
      const { headers } = headerGroup;
      const { left, right, center } = headers.reduce<{
        left: Header<RowData, unknown>[];
        right: Header<RowData, unknown>[];
        center: Header<RowData, unknown>[];
      }>(
        (acc, header) => {
          const position = header.column.getIsPinned() || 'center';
          acc[position].push(header);
          return acc;
        },
        { left: [], right: [], center: [] },
      );
      const allHeaders = [...left, ...getVirtualHeaders(center, virtualColumnIndexes), ...right];

      allHeaders.forEach((header) => {
        if (header.isPlaceholder) return;
        const { header: headerRenderer, footer: footerRenderer } = header.column.columnDef;

        if (typeof headerRenderer === 'function') {
          const renderer = headerRenderer(header.getContext());
          if (typeof renderer === 'function') {
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`title-${this.slotKey(header)}`, renderer(header.getContext())),
            );
          }

          if (header.id === this.currentDragging && typeof renderer === 'function') {
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`title-${header.id}--mask`, renderer(header.getContext())),
            );
          }
        }

        if (typeof footerRenderer === 'function') {
          const renderer = footerRenderer(header.getContext());
          if (typeof renderer === 'function') {
            renderedNodes.push(
              this.wrapWithSlotWithFallback(`footer-${this.slotKey(header)}`, renderer(header.getContext())),
            );
          }
        }
      });
    });

    const nextBodyCellDynamicSlotCache = includeBodyCells ? new Map<string, unknown>() : undefined;

    rows.forEach((row) => {
      const renderCells = row.getVisibleCells(virtualColumnIndexes);

      renderCells.forEach((cell) => {
        const renderer = cell.column.columnDef.cell;
        if (typeof renderer !== 'function' || renderer.length >= 1) return;

        const slotName = `cell-${this.slotKey(cell)}`;

        if (!includeBodyCells) {
          if (this.bodyCellDynamicSlotCache.has(slotName)) {
            renderedNodes.push(this.bodyCellDynamicSlotCache.get(slotName));
          }
          return;
        }

        const cellContent = renderer({} as never)(cell.getValue(), row, row.index);
        const wrappedNode = this.wrapWithSlotWithFallback(slotName, cellContent);
        nextBodyCellDynamicSlotCache?.set(slotName, wrappedNode);
        renderedNodes.push(wrappedNode);
      });
    });

    if (nextBodyCellDynamicSlotCache) {
      this.bodyCellDynamicSlotCache = nextBodyCellDynamicSlotCache;
    }

    return renderedNodes;
  }

  private clearBodyCellDynamicSlotCache() {
    this.bodyCellDynamicSlotCache.clear();
  }

  private handleHeadRowAction = (action: string, header: Header<RowData, unknown>) => {
    if (['clear-sort', 'sort-ascending', 'sort-descending'].includes(action)) {
      this.ksSorterClick.emit({ id: header.column.id, direction: header.column.getIsSorted() });
    }
    this.ksAction.emit(DetailArgs(action, header.column));
  };

  private handleHeaderDynamicRenderDeps = (
    headerId: string,
    children: unknown[],
    getPassThroughSlots?: () => VNode[],
  ) => {
    this.headerDynamicRenderDeps[headerId] = children;
    this.passThroughSlots = {
      ...this.passThroughSlots,
      [headerId]: getPassThroughSlots?.() || [],
    };
  };

  private handleMeasureRow = (el?: HTMLTableRowElement) => {
    this.rowVirtualizer?.measureElement(el);
  };

  protected override onWrapperScroll: EventListener = throttle((event: Event) => {
    const position = this.getScrollPosition(event.target as HTMLDivElement);
    this.updateScrollState(position);
    this.ksScrollPositionChange.emit(position);
    this.virtualController.notifyScroll(position);
  });

  protected override scrollToTablePosition(options?: TableScrollToPositionOptions): void {
    this.virtualController.scrollToPosition(options);
  }

  protected override renderSkeletonRows() {
    const { estimatedCount = DEFAULT_PAGE_SIZE, table } = this;
    const getEstimatedRowSize = (index: number) =>
      typeof this.estimatedRowHeight === 'function' ? this.estimatedRowHeight(index) : this.estimatedRowHeight;

    return Array.from({ length: estimatedCount }, (_, index) => {
      const estimatedRowSize = getEstimatedRowSize(index);

      return (
        <tr
          class={`${prefix}__tbody-row ${prefix}__tbody-row--skeleton`}
          style={estimatedRowSize ? { height: `${estimatedRowSize}px` } : undefined}
        >
          {table.getVisibleFlatColumns().map((column) => (
            <td
              class={`${prefix}__cell ${prefix}__tbody-cell`}
              style={{ width: `calc(var(--ks-comp-width-table-column-${column.id}) * 1px)` }}
            >
              <div class={`${prefix}__cell-content`}>
                <div
                  class={{
                    [`${prefix}__skeleton`]: true,
                    [`${prefix}__skeleton--selection`]: column.id === SELECTION_COLUMN_ID,
                    'animate-pulse': true,
                  }}
                />
              </div>
            </td>
          ))}
        </tr>
      );
    });
  }

  // eslint-disable-next-line max-lines-per-function
  override render() {
    const {
      bordered,
      columns,
      dataSource,
      draggable,
      resizable,
      size = 'md',
      loading,
      expandable,
      rowSelection,
      showTopPinningShadow,
      showStartPinningShadow,
      showEndPinningShadow,
      table,
    } = this;
    let rowsToVirtualize: Row<RowData>[] = [];
    let topRows: Row<RowData>[] = [];
    let virtualRows: VirtualItem[] = [];
    let virtualColumns: VirtualItem[] = [];
    let virtualColumnIndexes: number[] = [];
    let visibleFlatColumns = this.table.getVisibleFlatColumns();
    let virtualRowStyle: VirtualTableRenderState['virtualRowStyle'] = {};
    try {
      ({
        rowsToVirtualize,
        topRows,
        virtualRows,
        virtualColumns,
        virtualColumnIndexes,
        visibleFlatColumns,
        virtualRowStyle,
      } = this.virtualController.getRenderState());
    } catch (error) {
      console.error('Error getting rows:', error);
    }

    const enableTableFooter = columns.some((column) =>
      'columns' in column ? column.columns.some((subColumn) => subColumn.footer) : column.footer,
    );

    const hasPinnedRows = topRows.length > 0;
    const bodyRows = [...topRows, ...rowsToVirtualize].filter(
      (row) => !row.getParentRow() || row.getParentRow()?.getIsExpanded(),
    );
    const lastBodyRow = bodyRows[bodyRows.length - 1];
    const frameMode = this.frameMode ?? 'fill';

    return (
      <Host class="KsTable" style={this.getCssVariables()}>
        <div
          class={{
            [`${prefix}__content`]: true,
            [`${prefix}__content--frame-${frameMode}`]: true,
          }}
        >
          <div
            ref={(el) => {
              if (el) this.wrapperEl = el;
            }}
            part="base"
            class={{
              [`${prefix}__wrapper`]: true,
              [`${prefix}__wrapper--bordered`]: Boolean(bordered),
              [`${prefix}__wrapper--frame-${frameMode}`]: true,
            }}
            onScroll={this.onWrapperScroll}
            data-testid="ks-simple-table-ks-simple-table-xhTQoc"
          >
            <table
              class={{
                [prefix]: true,
                [`${prefix}--${size}`]: true,
                [`${prefix}--bordered`]: Boolean(bordered),
                [`${prefix}--top-shadowed`]: showTopPinningShadow,
                [`${prefix}--start-shadowed`]: showStartPinningShadow,
                [`${prefix}--end-shadowed`]: showEndPinningShadow,
                [`${prefix}--has-pinned-rows`]: hasPinnedRows,
              }}
            >
              <thead class={`${prefix}__thead`}>
                {table.getHeaderGroups().map((headerGroup) => {
                  const { headers } = headerGroup;
                  const { left, right, center } = headers.reduce<{
                    left: Header<RowData, unknown>[];
                    right: Header<RowData, unknown>[];
                    center: Header<RowData, unknown>[];
                  }>(
                    (acc, header) => {
                      const position = header.column.getIsPinned() || 'center';
                      acc[position].push(header);
                      return acc;
                    },
                    { left: [], right: [], center: [] },
                  );
                  const allHeaders = [...left, ...getVirtualHeaders(center, virtualColumnIndexes), ...right];

                  return (
                    <TableHeadRow
                      key={headerGroup.id}
                      prefix={prefix}
                      table={table}
                      rowSelection={this.rowSelection}
                      draggable={draggable}
                      headers={allHeaders}
                      resizable={resizable}
                      virtual
                      isLastPinned={!hasPinnedRows}
                      onAction={this.handleHeadRowAction}
                      contentPartName={this.headerContentPartName}
                      innerContentPartName={this.headerInnerContentPartName}
                      cellPartName={this.headerCellPartName}
                      style={virtualRowStyle}
                      slotKey={this.slotKey}
                      wrapWithSlot={this.wrapWithSlot}
                      setDynamicRenderDeps={this.handleHeaderDynamicRenderDeps}
                      passThroughSlots={this.passThroughSlots}
                      data-testid="ks-simple-table-ks-simple-table-sAVogH"
                    />
                  );
                })}
              </thead>

              <tbody
                class={{
                  [`${prefix}__tbody`]: true,
                  [`${prefix}__tbody--empty`]: !dataSource.length && !loading,
                }}
              >
                {!dataSource.length && (loading ? this.renderSkeletonRows() : this.renderEmptyState(true))}

                {topRows.map((row, index) => {
                  const isPinned = row.getIsPinned() === 'top';
                  const nextRow = topRows[index + 1];
                  const isLastPinned = isPinned && (!nextRow || nextRow.getIsPinned() !== 'top');

                  // Always render pinned rows while scrolling
                  return (
                    <TableBodyRow<RowData>
                      key={row.id}
                      part={
                        typeof this.rowPartName === 'function'
                          ? this.rowPartName(row.original, row, row.index)
                          : this.rowPartName
                      }
                      prefix={prefix}
                      row={row}
                      rowAlign={this.rowAlign}
                      loading={loading}
                      hideToggler={!(expandable?.shouldShowToggler?.(row) ?? true)}
                      hideSelection={!(rowSelection?.shouldShowSelection?.(row) ?? true)}
                      virtualItems={virtualColumns}
                      visibleColumns={visibleFlatColumns}
                      isLastPinned={isLastPinned}
                      isLastBodyRow={row === lastBodyRow}
                      contentPartName={this.contentPartName}
                      cellPartName={this.cellPartName}
                      cellSkeletonContent={this.cellSkeletonContent}
                      style={virtualRowStyle}
                      onRowClick={this.handleRowClick}
                      onRowHover={this.handleRowHover}
                      onRowHoverEnd={this.handleRowHoverEnd}
                      onCellPointerEnter={this.handleCellPointerEnter}
                      onCellPointerLeave={this.handleCellPointerLeave}
                      slotKey={this.slotKey}
                      data-testid={`ks-simple-table-ks-simple-table-vV6zYc-${row.id}`}
                    />
                  );
                })}

                <div style={{ position: 'relative', height: `${this.rowVirtualizer?.getTotalSize()}px` }}>
                  {virtualRows.map((virtualRow) => {
                    const row = rowsToVirtualize[virtualRow.index];
                    if (row?.getIsPinned()) return null;

                    return row ? (
                      <TableBodyRow<RowData>
                        key={row.id}
                        data-index={virtualRow.index}
                        measureRef={this.handleMeasureRow}
                        part={
                          typeof this.rowPartName === 'function'
                            ? this.rowPartName(row.original, row, row.index)
                            : this.rowPartName
                        }
                        prefix={prefix}
                        row={row}
                        rowAlign={this.rowAlign}
                        loading={loading}
                        hideToggler={!(expandable?.shouldShowToggler?.(row) ?? true)}
                        hideSelection={!(rowSelection?.shouldShowSelection?.(row) ?? true)}
                        contentPartName={this.contentPartName}
                        cellPartName={this.cellPartName}
                        cellSkeletonContent={this.cellSkeletonContent}
                        virtualItems={virtualColumns}
                        visibleColumns={visibleFlatColumns}
                        isLastBodyRow={row === lastBodyRow}
                        style={{
                          ...virtualRowStyle,
                          // height: `${virtualRow.size}px`,
                          transform: `translateY(${virtualRow.start}px)`,
                        }}
                        onRowClick={this.handleRowClick}
                        onRowHover={this.handleRowHover}
                        onRowHoverEnd={this.handleRowHoverEnd}
                        onCellPointerEnter={this.handleCellPointerEnter}
                        onCellPointerLeave={this.handleCellPointerLeave}
                        slotKey={this.slotKey}
                        data-testid={`ks-simple-table-ks-simple-table-vV6zYc-${row.id}`}
                      />
                    ) : null;
                  })}
                </div>

                <slot name="append" />
              </tbody>

              {enableTableFooter && (
                <tfoot class={`${prefix}__tfoot`}>
                  {table.getFooterGroups().map((footerGroup) => {
                    const { headers } = footerGroup;
                    const { left, right, center } = headers.reduce<{
                      left: Header<RowData, unknown>[];
                      right: Header<RowData, unknown>[];
                      center: Header<RowData, unknown>[];
                    }>(
                      (acc, header) => {
                        const position = header.column.getIsPinned() || 'center';
                        acc[position].push(header);
                        return acc;
                      },
                      { left: [], right: [], center: [] },
                    );
                    const allHeaders = [...left, ...getVirtualHeaders(center, virtualColumnIndexes), ...right];

                    return (
                      <TableFootRow
                        prefix={prefix}
                        headers={allHeaders}
                        virtual
                        loading={loading}
                        visibleColumns={visibleFlatColumns}
                        style={virtualRowStyle}
                        contentPartName={this.footerContentPartName}
                        cellPartName={this.footerCellPartName}
                        slotKey={this.slotKey}
                      />
                    );
                  })}
                </tfoot>
              )}
            </table>
          </div>
          {frameMode === 'content' && <div class={`${prefix}__spacer`} aria-hidden="true" />}
        </div>

        {this.renderPagination()}
      </Host>
    );
  }

  // should override, or the initialized value will not exist.
  @State() protected override passThroughSlots: Record<string, VNode[]> = {};
  protected override headerDynamicRenderDeps: Record<string, unknown[]> = {};

  ////// DEPS //////
  protected override __DEPS__() {
    return [<ks-dropdown-button />];
  }
}
